INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29801, 'Revelation 14:6', 'Revelation', 14, 6, '&nbsp;بيا ما د آسمان په مينځ کښې بله فرښته په الوتو وليدله چې د زمکې هر قوم، خيل، ژبې او خلقو له يې د تل زيرے ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29802, 'Revelation 14:7', 'Revelation', 14, 7, '&nbsp;هغې په اوچت آواز چغې کړې چې، ”د خُدائ پاک نه يرېږئ او د هغۀ ثنا ووايئ ځکه چې د هغۀ د عدالت وخت راغلے دے. او د هغۀ عبادت وکړئ چا چې آسمان او زمکه، سمندر او د اوبو چينې پېدا کړى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29803, 'Revelation 14:8', 'Revelation', 14, 8, '&nbsp;بيا هغې نه وروستو بله دوېمه فرښته راغله او هغې وئيل چې، ”وغورزېدو، لوئ بابل وغورزېدو چې په ټولو قومونو يې د خپلې زناکارۍ او مستۍ د شرابو نه څښلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29804, 'Revelation 14:9', 'Revelation', 14, 9, '&nbsp;بيا هغې نه وروستو بله دريمه فرښته راغله او په اوچت آواز يې چغې کړې، ”هر هغه څوک چې د بلا او د هغې بُت ته عبادت کوى او د هغې نښه په تندى يا په خپل لاس لګوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29805, 'Revelation 14:10', 'Revelation', 14, 10, '&nbsp;هغوئ به د خُدائ پاک د قهر او د غضب مے وڅښى کوم چې هغۀ د خپل سخت غضب په پيالۍ کښې اچولى دى. هغوئ به د پاکو فرښتو او د ګډُورى په وړاندې په اور او د ګوګړو په شغلو کښې عذابولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29806, 'Revelation 14:11', 'Revelation', 14, 11, '&nbsp;او د هغوئ د عذاب لوګے به تل تر تله راوچتيږى او هر هغه څوک چې بلا يا د هغۀ د بُت عبادت کوى يا د هغۀ د نوم نښه اخلى، د هغوئ به نۀ د شپې او نۀ د ورځې آرام وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29807, 'Revelation 14:12', 'Revelation', 14, 12, '&nbsp;په دې کښې د هغه مقدسينو زغم او برداشت ضرور دے چې د خُدائ پاک حُکمونه منى او د عيسىٰ وفادار پاتې کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29808, 'Revelation 14:13', 'Revelation', 14, 13, '&nbsp;نو بيا ما د آسمان نه يو آواز واورېدو چې وئيل يې، ”دا وليکه، بختور دى هغه څوک چې د دې نه پس به په مالِک کښې مړۀ کيږى.“ او روحُ القُدس فرمائى چې، ”بې‌شکه بختور دى ځکه چې له دې نه پس به هغوئ د کړېدو نه په آرام وى، ولې چې د دوئ نيک عملونه به ورسره ملګرى وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29809, 'Revelation 14:14', 'Revelation', 14, 14, '&nbsp;بيا ما وکتل نو يوه سپينه وريځ راښکاره شوه او په هغې چې څوک ناست وو هغه د اِبن آدم په شان وو. د هغۀ په سر د سرو زرو تاج وو او په لاس کښې يې تېرۀ لور وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29810, 'Revelation 14:15', 'Revelation', 14, 15, '&nbsp;يوه بله فرښته د خُدائ د کور نه بهر راووتله او په وريځ ناست ته يې په اوچت آواز ووئيل چې، ”خپل لور ورواچوه او وريبه، ځکه چې د فصل د رېبلو وخت راغلے دے او د دُنيا فصل مکمل پوخ شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29811, 'Revelation 14:16', 'Revelation', 14, 16, '&nbsp;نو هغه څوک چې په وريځې ناست وو هغۀ خپل لور دُنيا ته ورواچولو او د هغې فصل يې ورېبلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29812, 'Revelation 14:17', 'Revelation', 14, 17, '&nbsp;بيا يوه بله فرښته د خُدائ پاک د آسمانى کور نه راووتله او د هغې سره هم يو تېرۀ لور وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29813, 'Revelation 14:18', 'Revelation', 14, 18, '&nbsp;او بيا بله فرښته د قربان‌ګاه نه راووتله، دا هغه فرښته وه چې په اور يې اختيار وو، او هغې د تېرۀ لور لرونکى ته په اوچت آواز چغه کړه چې، ”خپل تېرۀ لور ورواچوه او په زمکه د انګورو د بوټو نه فصل راغونډ کړه ځکه چې انګور يې پاخۀ شوى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29814, 'Revelation 14:19', 'Revelation', 14, 19, '&nbsp;نو فرښتې خپل لور ورواچولو او په دُنيا يې د انګورو د بوټو فصل راټول کړو او هغه يې د خُدائ پاک د غضب په هغه لويه لنګرۍ کښې ورواچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29815, 'Revelation 14:20', 'Revelation', 14, 20, '&nbsp;انګور يې د ښار نه بهر په لنګرۍ کښې دومره نچوړ کړل چې تر يو سل اتيا ميله پورې د هغې نه د وينو سېلاب روان شو او دا وينې دومره بره روانې وې چې د آسونو واګو ته اورسېدې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29816, 'Revelation 15:1', 'Revelation', 15, 1, '&nbsp;بيا ما په آسمان کښې بله يوه لويه او عجيبه نښه وليدله. اووۀ فرښتې وې چې ورسره د ټولو نه آخرى اووۀ افتونه وُو، ځکه چې په دې افتونو سره د خُدائ پاک قهر سوړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29817, 'Revelation 15:2', 'Revelation', 15, 2, '&nbsp;او ما وليدل چې د شيشې د سمندر په شان راښکاره شو چې اور په کښې ګډ شوے وو، او د شيشې د سمندر سره هغه خلق ولاړ وُو چې په بلا او د هغې د بُت او د هغې د نوم په شمېر فتح موندلې وه. د هغوئ په لاسونو کښې د خُدائ پاک ورکړى ستارونه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29818, 'Revelation 15:3', 'Revelation', 15, 3, '&nbsp;هغوئ د خُدائ پاک د غلام موسىٰ او ګډُورى حمدونه ووئيل چې، ”اے مالِکه قادر مطلق خُدايه پاکه، ستا کارونه لوئ او عجيبه دى او ستا لارې د حق او رښتيا دى، اے د قومونو بادشاه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29819, 'Revelation 15:4', 'Revelation', 15, 4, '&nbsp;اے مالِکه څوک به يره ونۀ کړى او ستا د نوم لوئى به ونۀ کړى؟ ځکه چې يواځې تۀ پاک يې. ټول قومونه به راشى او ستا په وړاندې به عبادت وکړى ځکه چې ستا د صداقت کارونه ښکاره شوى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29820, 'Revelation 15:5', 'Revelation', 15, 5, '&nbsp;او د دې نه پس ما وليدل چې په آسمان کښې د خُدائ په کور کښې د ګواهۍ د خېمې پاک ځائ کولاو شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29821, 'Revelation 15:6', 'Revelation', 15, 6, '&nbsp;او د هغې نه اووۀ فرښتې د اوو افتونو سره راووتلې او هغوئ د کتان جامې اغوستې وې چې صفا او ځلېدونکې وې او په سينو يې د سرو زرو سينه بندونه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29822, 'Revelation 15:7', 'Revelation', 15, 7, '&nbsp;بيا په څلورو جاندارو کښې يو هغه اووۀ فرښتو ته د سرو زرو اووۀ جامونه ورکړل چې د خُدائ پاک د قهر نه ډک وُو، د هغه خُدائ پاک چې تل تر تله ژوندے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29823, 'Revelation 15:8', 'Revelation', 15, 8, '&nbsp;او د خُدائ پاک کور د خُدائ د جلال او قُدرت د لوګى نه ډک شو او تر هغې هيڅوک ورننوتے نۀ شو ترڅو چې د اووۀ فرښتو اووۀ افتونه پوره شوى نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29824, 'Revelation 16:1', 'Revelation', 16, 1, '&nbsp;بيا ما د خُدائ پاک د کور نه يو اوچت آواز واورېدو چې هغه اووۀ فرښتو ته يې وئيل چې، ”لاړې شئ او د خُدائ پاک د قهر اووۀ جامونه په زمکه توئ کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29825, 'Revelation 16:2', 'Revelation', 16, 2, '&nbsp;نو اوله فرښته لاړه او په زمکه يې خپل جام توئ کړو او د ناسور خوراکى دانې په هغه خلقو ښکاره شوې چې د بلا نښه يې په ځان کښې وه او هغه بُت ته يې عبادت کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29826, 'Revelation 16:3', 'Revelation', 16, 3, '&nbsp;او دوېمې فرښتې خپل جام په سمندر کښې توئ کړو او د هغې اوبۀ د مړى د وينې په شان شوې او په سمندر کښې هر ژوندے څيز مړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29827, 'Revelation 16:4', 'Revelation', 16, 4, '&nbsp;او درېمې فرښتې خپل جام په دريابونو او په چينو کښې توئ کړو او وينې شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29828, 'Revelation 16:5', 'Revelation', 16, 5, '&nbsp;بيا ما واورېدل چې په اوبو اختيار لرونکې فرښتې ووئيل چې، ”اے قُدوسه خُدايه، تۀ چې يې او وې، تۀ په خپل عدالت کښې صادق يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29829, 'Revelation 16:6', 'Revelation', 16, 6, '&nbsp;ځکه چې هغوئ د مقدسينو او ستا د نبيانو وينې توئ کړې دى او تا هغوئ ته د څښلو دپاره وينې ورکړې، هغوئ د دې سزا لائق دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29830, 'Revelation 16:7', 'Revelation', 16, 7, '&nbsp;او ما د قربان‌ګاه نه يوه چغه واورېدله، ”آو، مالِکه خُدايه پاکه، تۀ په ټولو قادر يې، ستا ټولې فېصلې رښتينې او په حقه دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29831, 'Revelation 16:8', 'Revelation', 16, 8, '&nbsp;او څلورمې فرښتې خپل جام په نمر توئ کړو او دا اختيار ورله ورکړے شو چې په خپلو شغلو خلق وسيزى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29832, 'Revelation 16:9', 'Revelation', 16, 9, '&nbsp;او هغوئ بد بد وسوزېدل خو هغوئ د خُدائ پاک په نوم کُفر ووئيلو، چا سره چې د دې افتونو د نازلولو اختيار دے، خو هغوئ د توبه ويستلو نه اِنکارى شول او نۀ يې د هغۀ ثنا ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29833, 'Revelation 16:10', 'Revelation', 16, 10, '&nbsp;او پينځمې فرښتې د بلا په تخت خپل جام توئ کړو او د هغۀ په بادشاهۍ کښې تيارۀ شوله. او خلقو د درد نه خپل غاښونه چيچل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29834, 'Revelation 16:11', 'Revelation', 16, 11, '&nbsp;او هغوئ د خپل درد او د ناسور په وجه آسمانى خُدائ پاک ته کُفر ووې، او څۀ بد کارونه چې هغوئ کړى وُو، د هغې نه يې توبه ونۀ کړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29835, 'Revelation 16:12', 'Revelation', 16, 12, '&nbsp;او شپږمې فرښتې خپل جام د فرات په لوئ سيند کښې توئ کړو او د هغې اوبۀ وچې شوې چې د نمرخاتۀ د بادشاهانو دپاره لار تياره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29836, 'Revelation 16:13', 'Revelation', 16, 13, '&nbsp;بيا ما وليدل چې د اژدها، د بلا، او د دروغژن نبى د خولې نه د چيندخانو په شان درې پيريان راووتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29837, 'Revelation 16:14', 'Revelation', 16, 14, '&nbsp;دا هغه پيريان دى چې معجزې ښائى، هغوئ د دې دپاره ځى چې د دُنيا ټول بادشاهان د قادر خُدائ پاک د لوئ ورځې د جنګ دپاره راجمع کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29838, 'Revelation 16:15', 'Revelation', 16, 15, '&nbsp;”ګورئ، زۀ د غل په شان درځم. بختور دے هغه چې بېدار وى او جامې يې اغوستې وى نو چې هغه به بربنډ نۀ شى او خلق به د هغۀ شرم ونۀ وينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29839, 'Revelation 16:16', 'Revelation', 16, 16, '&nbsp;نو هغوئ بادشاهان هغه ځائ ته راجمع کړل چې په عبرانۍ کښې ورته ارمِګدون وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29840, 'Revelation 16:17', 'Revelation', 16, 17, '&nbsp;بيا اوومې فرښتې خپل جام په هوا توئ کړو او د خُدائ د کور د تخت نه يو اوچت آواز راغلو چې هغۀ وفرمائيل چې، ”هر څۀ پوره شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29841, 'Revelation 16:18', 'Revelation', 16, 18, '&nbsp;له دې نه پس د برېښنا شُغلې او د تندر ګړزا او يوه دومره سخته زلزله راغله چې د بنى آدم د پېدايښت راسې چرې هم نۀ وه راغلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29842, 'Revelation 16:19', 'Revelation', 16, 19, '&nbsp;او هغه لوئ ښار په درېو حِصو تقسيم شو او د دُنيا ښارونه ونړېدل، او خُدائ پاک ته لوئ بابل راياد شو بلکې د خپل غضب او قهر نه ډکه پياله يې په هغوئ وڅښله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29843, 'Revelation 16:20', 'Revelation', 16, 20, '&nbsp;هره يوه جزيره غېبه شوله او يو غر هم ليدے نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29844, 'Revelation 16:21', 'Revelation', 16, 21, '&nbsp;او په بنى آدمو له آسمان نه تقريباً پنځوس کلو وزن برابر ږلۍ وورېدله او هغوئ د ږلۍ په افت خُدائ پاک ته کُفر ووئيلو ځکه چې هغه افت ډېر سخت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29845, 'Revelation 17:1', 'Revelation', 17, 1, '&nbsp;بيا هغه اووۀ فرښتې چې جامونه يې نيولى وُو، په هغوئ کښې يوه ما له راغله او وې وئيل چې، ”راځه چې زۀ درته د هغې لوئ کنجرې اَنجام وښايم چې د ډېرو سمندرونو دپاسه په تخت ناسته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29846, 'Revelation 17:2', 'Revelation', 17, 2, '&nbsp;د دُنيا خلق په هغه شرابو نشه شول کوم چې هغې دوئ ته ورکړى وُو او بيا يې د هغې سره زنا وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29847, 'Revelation 17:3', 'Revelation', 17, 3, '&nbsp;روحُ القُدس په ما غلبه وکړه او بيا فرښتې زۀ بيابان ته بوتلم. هلته ما يوه ښځه وليده چې په يوې سرې بلا سوره وه. چې د هغې په ټول بدن کُفر ليکلے وو او اووۀ سرونه او لس ښکرونه يې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29848, 'Revelation 17:4', 'Revelation', 17, 4, '&nbsp;هغه ښځې کاسنى سرې جامې اغوستې وې چې د سرو زرو په کالو، جواهراتو او ملغلرو سنګار شوې وه. د هغې په لاس کښې د سرو زرو پيالۍ وه چې د پليتۍ او د هغې د حرامکارۍ د ناپاکۍ نه ډکه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29849, 'Revelation 17:5', 'Revelation', 17, 5, '&nbsp;او د هغې په تندى يو نوم ليکلے وو چې يو پټ راز دے، ”لوئ بابل، د کنجرو او د دُنيا د هرې پليتۍ مور.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29850, 'Revelation 17:6', 'Revelation', 17, 6, '&nbsp;او ما وليدل چې هغه ښځه د مقدسينو په وينه او د عيسىٰ د شهيدانو په وينه په نشه وه. کله چې ما هغه وليده نو زۀ ډېر حېران شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29851, 'Revelation 17:7', 'Revelation', 17, 7, '&nbsp;خو فرښتې راته ووئيل چې، ”دا تۀ دومره ولې حېران يې؟ زۀ به درته د دې ښځې او دا چې په کومې بلا سوره ده چې اووۀ سرونه او لس ښکرونه يې دى، د هغې راز ښکاره کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29852, 'Revelation 17:8', 'Revelation', 17, 8, '&nbsp;کومه بلا چې تا وليدله، هم هغه ده چې ژوندۍ وه خو اوس ژوندۍ نۀ ده، هغه به د عالمِ ارواح نه راوخېژى او هلاکه به شى. او په دُنيا کښې هغه خلق چې د چا نومونه چې له ازل نه د ژوندون په کِتاب کښې نۀ دى ليکلے شوى، هغوئ به د دې مړې بلا په بيا راښکاره کېدو حېران شى. ځکه چې هغه مخکښې وه، اوس نشته خو بيا به راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29853, 'Revelation 17:9', 'Revelation', 17, 9, '&nbsp;او د دې خبرو د پوهېدلو دپاره ډېر حِکمت په کار دے. دا اووۀ سرونه هغه اووۀ غرونه دى چې دا ښځه پرې ناسته ده، خو دوئ هم اووۀ بادشاهان دى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29854, 'Revelation 17:10', 'Revelation', 17, 10, '&nbsp;چې پينځۀ بادشاهان پخوا تېر شوى دى او يو ژوندے دے او يو بل به راځى، او کله چې هغه راشى نو هغه به د لږ وخت دپاره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29855, 'Revelation 17:11', 'Revelation', 17, 11, '&nbsp;او هغه بلا چې يو وخت ژوندۍ وه او اوس ژوندۍ نۀ ده، هغه اتم بادشاه دے، خو بيا هم هغه د اوو نه يو دے او هغه به هلاک شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29856, 'Revelation 17:12', 'Revelation', 17, 12, '&nbsp;کوم لس ښکرونه چې تا وليدل، هغه لس بادشاهان دى چې هغوئ لا حکومت نۀ دے شروع کړے، خو هغوئ به د يوې ګينټې دپاره د بلا سره د بادشاهۍ اختيار ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29857, 'Revelation 17:13', 'Revelation', 17, 13, '&nbsp;د هغه ټولو يو مقصد دے چې خپل طاقت او اختيار بلا له ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29858, 'Revelation 17:14', 'Revelation', 17, 14, '&nbsp;هغوئ به د ګډُورى سره جنګ وکړى خو ګډُورے به په هغوئ کامياب شى ځکه چې هغه د مالِکانو مالِک او د بادشاهانو بادشاه دے، او هغوئ هم چې بللے شوى دى، غوره شوى دى او وفادار دى ورسره ملګرى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29859, 'Revelation 17:15', 'Revelation', 17, 15, '&nbsp;بيا فرښتې ما ته ووئيل چې، ”تا چې کوم سمندر وليدو چې لويه کنجره پرې ناسته ده، دا د خلقو اُمتونه، قومونه او ژبې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29860, 'Revelation 17:16', 'Revelation', 17, 16, '&nbsp;هغه لس ښکرونه چې تا وليدل، هغه به سره د بلا د دې کنجرې نه نفرت کوى، هغوئ به دا بربنډه او برباده کړى او د هغې غوښه به وخورى او په اور به يې ايرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29861, 'Revelation 17:17', 'Revelation', 17, 17, '&nbsp;ځکه چې خُدائ پاک د خپل مقصد د پوره کولو دپاره د دوئ په زړُونو کښې دا خبره اچولې ده چې دوئ په يو زړۀ سره بلا ته د خپلې بادشاهۍ اختيار ورکړى، ترڅو چې د خُدائ پاک کلام د دوئ په حقله پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29862, 'Revelation 17:18', 'Revelation', 17, 18, '&nbsp;دا ښځه چې تا وليده هغه لوئ ښار دے چې د دُنيا په بادشاهانو حکومت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29863, 'Revelation 18:1', 'Revelation', 18, 1, '&nbsp;د دې نه پس ما يوه بله فرښته د آسمان نه په راکوزېدو وليدله او د هغې لوئ اختيار وو او زمکه د هغې په جلال رڼا شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29864, 'Revelation 18:2', 'Revelation', 18, 2, '&nbsp;بيا هغې په اوچت آواز چغه کړه، ”پرېوتو، لوئ بابل پرېوتو. هغه د پيريانو کور، د ټولو ناپاکو روحونو اډه، او د مردارو مارغانو او د مردارو او حرامو ځناورو کور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29865, 'Revelation 18:3', 'Revelation', 18, 3, '&nbsp;ځکه چې ټولو قومونو د هغې د مستۍ او بدکارۍ شراب څښلى دى، د دُنيا بادشاهانو د هغې سره بدکارى کړې ده، او د دُنيا سوداګرانو د هغې د عياشۍ په سبب دولت راغونډ کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29866, 'Revelation 18:4', 'Revelation', 18, 4, '&nbsp;بيا ما د آسمان نه يو بل آواز واورېدو چې وئيل يې، ”اے زما خلقو، د دې نه رابهر شئ چې د دې په ګناهونو کښې شريک نۀ شئ او چې د هغې په افتونو کښې شامل نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29867, 'Revelation 18:5', 'Revelation', 18, 5, '&nbsp;ځکه چې د هغې ګناهونه تر آسمانه رسېدلى دى او خُدائ پاک د هغې بد کارونه هېر کړى نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29868, 'Revelation 18:6', 'Revelation', 18, 6, '&nbsp;هغې ته د خپلو کړو بدله ورکړئ، هغې چې کوم ناروا کارونه کړى دى، هغه دوه چنده ورکړئ، او هغې چې په کومې پيالۍ کښې شراب ګډ کړى دى هغه دوه چنده ګډه کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29869, 'Revelation 18:7', 'Revelation', 18, 7, '&nbsp;هغې چې هر څومره لوئى او عياشى وکړه هم هغه هومره ورته عذاب او وير ورکړئ. هغه په زړۀ کښې دا وائى چې زۀ د تخت مَلِکه يم، زۀ به چرې هم د کونډو په شان ويرونه نۀ کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29870, 'Revelation 18:8', 'Revelation', 18, 8, '&nbsp;نو په دې وجه به په هغې په يوه ورځ دومره افتونه راشى، يعنې مرګ، ويره او قحط. او په اور به هم وسوزولے شى ځکه چې مالِک خُدائ پاک زورَور دے چې د دې فېصله يې واوروله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29871, 'Revelation 18:9', 'Revelation', 18, 9, '&nbsp;د زمکې بادشاهانو چې د هغې سره بدکارى وکړه او د هغې په عياشۍ کښې شامل شول، هر کله چې هغوئ د دې د سوزېدلو لوګے ووينى نو هغوئ به پرې ژړا او وير وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29872, 'Revelation 18:10', 'Revelation', 18, 10, '&nbsp;هغوئ به لرې ولاړ وى او د هغې په عذاب به د يرې دا وائى چې، ”افسوس، افسوس په لوئ ښار د بابل، په زورَور ښار، چې تۀ په يوه ګينټه کښې برباد شوې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29873, 'Revelation 18:11', 'Revelation', 18, 11, '&nbsp;د دُنيا سوداګران به هم په بابل وير او ژړا کوى ځکه چې بيا به هيڅوک هم د هغوئ نوره سودا وانۀ خلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29874, 'Revelation 18:12', 'Revelation', 18, 12, '&nbsp;د سرو زرو، د سپينو زرو، قيمتى کاڼو، د ملغلرو، د کتان نرمې کپړې، کاسنى کپړې، د رېښمو او سرې کپړې، د هر قسم د عُودو لرګى، د هاتى غاښونه، د هر قسمه قيمتى لرګو د زېړو، د اوسپنو او د مرمرو څيزونه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29875, 'Revelation 18:13', 'Revelation', 18, 13, '&nbsp;او ورسره د دارچينى، مصالحې، خوشبويۍ عطر، د مُر چيړ، لوبان، مے، تېل، خاص مېده، غنم، او څاروى، ګډې، آسونه، جنګى ګاډۍ، غلامان او جنګى قيديان.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29876, 'Revelation 18:14', 'Revelation', 18, 14, '&nbsp;هغوئ به وائى چې، ”کوم ښۀ څيزونو ته چې ستا خواهش وو، هغه ستا د لاس نه وتلې دى، ستا ټول مال دولت او شان و شوکت ورک دے او بيا به دا چرې هم په لاس در نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29877, 'Revelation 18:15', 'Revelation', 18, 15, '&nbsp;او هغه سوداګرانو چې د دې ښار په تجارت مالداره شوى وُو هغوئ هم به د هغې د عذاب د يرې نه لرې ولاړ وى، ژړا او وير به پرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29878, 'Revelation 18:16', 'Revelation', 18, 16, '&nbsp;او داسې به وائى چې، ”افسوس، افسوس، په دې لوئ ښار چې د کتان او کاسنى جامې به يې اغوستې وې او په سرو زرو او قيمتى کاڼو او ملغلرو به يې خپل ځان سنګار کړے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29879, 'Revelation 18:17', 'Revelation', 18, 17, '&nbsp;افسوس چې په يوه ګينټه کښې د دې ټوله دبدبه برباده شى.“ بيا ټول د سمندرى جهازونو کپتانان، سمندرى مسافران او ماڼکيان او هغه څوک چې په سمندرى تجارت خپله ګزاره کوى، به لرې ودريږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29880, 'Revelation 18:18', 'Revelation', 18, 18, '&nbsp;او کله چې د هغې د سوزېدلو لوګى ووينى نو چغې به کړى، ”د دې لوئ ښار په شان بل داسې ښار چرته دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29881, 'Revelation 18:19', 'Revelation', 18, 19, '&nbsp;او هغوئ به په خپلو سرونو خاورې واچوى، وير او ژړا به پرې کوى او داسې به وائى چې، ”افسوس، افسوس، په هغه لوئ ښار چې د چا په تجارت د سمندرى جهازُونو مالِکان مالداره شول، کوم چې په يوه ګينټه کښې تباه او برباد شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29882, 'Revelation 18:20', 'Revelation', 18, 20, '&nbsp;د هغې د اَنجام په ليدو اے آسمانه خوشحالى وکړه، اے مقدسينو، رسولانو او نبيانو، په هغې خوشحالۍ وکړئ، ځکه چې خُدائ پاک ستاسو د انتقام اخستو په وجه په هغې د عدالت فېصله وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29883, 'Revelation 18:21', 'Revelation', 18, 21, '&nbsp;او بيا يوې قوتناکې فرښتې د ژرندې د يو غټ پل په شان کاڼے راواخستو او سمندر ته يې ورګزار کړو او وې وئيل چې، ”دغه شان به د بابل لوئ ښار ونړولے شى او بيا به يې هيڅوک ونۀ وينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29884, 'Revelation 18:22', 'Revelation', 18, 22, '&nbsp;او بيا به هيچرې په تا کښې د ستار، سندرغاړو، شپيلۍ او د بيګل آوازونه وانۀ ورېدے شى، او د يو کسب، کسبګر به هم په تا کښې ونۀ ليدے شى، او بيا به په تا کښې د ژرندې غرار وانۀ ورېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29885, 'Revelation 18:23', 'Revelation', 18, 23, '&nbsp;او نور به په تا کښې ډيوه بله نۀ شى او په تا کښې به بيا د زلمى او د ناوې خبرې وانۀ ورېدے شى. يو وخت وو چې ستا تاجران د دُنيا زورَور خلق وُو او تا په خپل جادو ټول قومونه دوکه کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29886, 'Revelation 18:24', 'Revelation', 18, 24, '&nbsp;ستا په کوڅو کښې د هغه نبيانو او مقدسينو او د هغه خلقو بهېدلې وينه وليدلے شوه چې په ټوله دُنيا کښې وژلے شوى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29887, 'Revelation 19:1', 'Revelation', 19, 1, '&nbsp;د دې نه پس ما په آسمان کښې د ګڼو خلقو اوچت آوازونه واورېدل، هغوئ چغې وهلې چې، ”ثنا صِفت دې وى مالِک خُدائ ته، خلاصون، لوئى او طاقت زمونږ د خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29888, 'Revelation 19:2', 'Revelation', 19, 2, '&nbsp;ځکه چې د هغۀ فېصلې رښتينې او په حقه دى او هغۀ د لوئې کنجرې د سزا فېصله وکړه چا چې په خپلې حرامکارۍ دا دُنيا ګډه وډه کړه او د هغې نه يې د خپلو خادِمانو د وينې بدل واخستو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29889, 'Revelation 19:3', 'Revelation', 19, 3, '&nbsp;هغوئ بيا چغې کړې چې، ”ثنا صِفت دې وى د مالِک خُدائ، د بابل لوګے تل تر تله خېژى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29890, 'Revelation 19:4', 'Revelation', 19, 4, '&nbsp;او هغه څليريشت مشران او څلور جاندار خُدائ پاک ته په سجده شول څوک چې په تخت ناست دے او هغوئ هم چغې کړې چې، ”آمين، ثنا صِفت دې وى د مالِک خُدائ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29891, 'Revelation 19:5', 'Revelation', 19, 5, '&nbsp;بيا د تخت د طرف نه يو آواز راغے چې، ”اے زمونږ د خُدائ پاک ټولو خادِمانو چې د هغۀ نه ويرېږئ، اے لويو او وړو، د خُدائ پاک ثنا وايئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29892, 'Revelation 19:6', 'Revelation', 19, 6, '&nbsp;بيا ما د ډېرو کسانو داسې آواز واورېدو لکه د سيند د اوبو غړمبار او يا لکه د تندر د ګړزار، او هغوئ چغې وهلې چې، ”ثنا صِفت دې وى د مالِک خُدائ، مالِک زمونږ قادر مطلق خُدائ پاک بادشاه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29893, 'Revelation 19:7', 'Revelation', 19, 7, '&nbsp;راځئ چې خوشحاله شُو او د خوشحالۍ نه چغې کړُو او د هغۀ لوئى بيان کړُو ځکه چې د ګډورى د وادۀ ورځ راغلې ده او د هغۀ ناوې ځان سمبال کړے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29894, 'Revelation 19:8', 'Revelation', 19, 8, '&nbsp;او ورته د کتان نرمې جامې ورکړے شوې دى چې صفا ځلېدونکې دى.“ او دا نرم کتان د مقدسينو ښۀ کارونه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29895, 'Revelation 19:9', 'Revelation', 19, 9, '&nbsp;بيا فرښتې ما ته ووئيل چې، ”دا وليکه چې، بختور دى هغه خلق چې د ګډُورى د وادۀ مېلمستيا ته رابللے شوى دى.“ او نور يې ووئيل چې، ”دا د خُدائ پاک برحق کلام دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29896, 'Revelation 19:10', 'Revelation', 19, 10, '&nbsp;نو بيا زۀ په دې د هغۀ په پښو کښې په سجده پرېوتلم خو ما ته يې ووئيل چې، ”نه، داسې مۀ کوه. زۀ هم ستا او ستا د وروڼو په شان يو خادِم يم چې د عيسىٰ ګواهى ورکوى. او صرف خُدائ پاک ته سجده کوه. کوم حقيقت چې د عيسىٰ په وسيله مونږ ته څرګند شو هم هغه نبيانو ته د پېشګويو الهام ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29897, 'Revelation 19:11', 'Revelation', 19, 11, '&nbsp;بيا ما آسمان پرانستے وليدو او هلته زما په وړاندې يو سپين آس وو او د هغۀ د سوارۀ نوم وفادار او رښتينے دے، ځکه چې هغه په عدالت کښې او په جنګ کښې په حقه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29898, 'Revelation 19:12', 'Revelation', 19, 12, '&nbsp;او د هغۀ سترګې د اور د شغلو په شان دى او په سر يې ډېر تاجونه دى. په هغې يو نوم ليکلے شوے دے چې بې له دۀ نه پرې نور هيڅوک نۀ پوهيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29899, 'Revelation 19:13', 'Revelation', 19, 13, '&nbsp;او هغۀ په وينو لړلې جامې اغوستې وې او د هغۀ نوم د خُدائ پاک کلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29900, 'Revelation 19:14', 'Revelation', 19, 14, '&nbsp;او آسمانى لښکرې په سپينو آسونو سورې ورپسې وې چې د سپين او صفا نرم کتان جامې يې اغوستې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');